import request from '@/utils/request'
import i18n from '@/i18n/i18n'
export function getOpeninfo(params) {
  return request({
    url: '/game' + params.gametype + '/getOpeninfo',
    method: 'get'
  }).then(res => {
    return res
  })
}
export function getGameinfo(params) {
  return request({
    url: '/game' + params.gametype + '/getGameinfo',
    method: 'get'
  }).then(res => {
    for (let index = 0; index < res.gamelist.length; index++) {
      for (let index2 = 0; index2 < res.gamelist[index].list.length; index2++) {
        if(index2==0){
          res.gamelist[index].list[index2].active = true
        }else{
          res.gamelist[index].list[index2].active = false
        }
        if(res.gamelist[index].list[index2].playname2==='二全中'){
          res.gamelist[index].list[index2].limitSelect=2
        }else if(res.gamelist[index].list[index2].playname2==='三中二'||res.gamelist[index].list[index2].playname2==='三全中'){
          res.gamelist[index].list[index2].limitSelect=3
        }else if(res.gamelist[index].playname1==='连肖连尾'){
          if(index2<5){
            res.gamelist[index].list[index2].limitSelect=index2+1
          }else{
            res.gamelist[index].list[index2].limitSelect=index2-4
          }
        }else if(res.gamelist[index].playname1==='自选不中'){
          res.gamelist[index].list[index2].limitSelect=index2+5
          if(index2>2){
            res.gamelist[index].list[index2].limitSelectMax = index2+7
          }else{
            res.gamelist[index].list[index2].limitSelectMax = index2+8
          }
        }
        for (let index3 = 0; index3 < res.gamelist[index].list[index2].list.length; index3++) {
          // const optionname = res.gamelist[index].list[index2].list[index3].optionname
          // const playname1 = res.gamelist[index].playname1
          // const playname2 = res.gamelist[index].list[index2].playname2
          res.gamelist[index].list[index2].list[index3].active = false
          res.gamelist[index].list[index2].list[index3].styleName = 'game-item'
          if(res.gamelist[index].list[index2].list[index3].color){

          }else{
            res.gamelist[index].list[index2].list[index3].color = ''
          }
        }
      }
    }
    return res
  }).catch(err=>{
    console.log(err);
  });
}
