<template>
  <div class="detail-view-lhc">
    <title-line-num :title="title" />
    <div class="game-info">
      <div class="title">{{ gameInfo.openissue }} 期开奖结果</div>
      <div v-if="gameInfo.open1" class="open-info" @click="showOpenList=false">
        <div v-for="i in 6" :key="i" class="open-item">
          <div :class="'open_'+gameInfo['open'+(i)].split(',')[2]">{{ gameInfo['open'+(i)].split(',')[0] }}</div>
          <div class="text-line">{{ gameInfo['open'+(i)].split(',')[1]+'/'+gameInfo['open'+(i)].split(',')[3] }}</div>
        </div>
        <!-- <span class="text-icon">=</span> -->
        <div class="open-item">
          <div :class="'open_'+gameInfo['open'+(7)].split(',')[2]">{{ gameInfo['open'+(7)].split(',')[0] }}</div>
          <div class="text-line">{{ gameInfo['open'+(7)].split(',')[1]+'/'+gameInfo['open'+(7)].split(',')[3] }}</div>
        </div>
        <div :class="!showOpenList?'arrow':'arrowbottom'" @click.stop="showOpenList=!showOpenList" />
      </div>
      <div class="split-line" />
      <div class="status">
        <div class="new-no">{{ gameInfo.curissue }} 期</div>
        <div class="status-right">
          <div class="curissuestatus">{{ gameInfo.curissuestatus==='1'?'已封单':gameInfo.curissuestatus==='2'?'开奖中':'' }}</div>
          <div v-if="gameInfo.curissuestatus!=='2'" class="curissuecountdown-class">
            <div class="time-label">{{ gameInfo.curissuestatus==='1'?'开奖':'下注' }}倒计时：</div>
            <div class="time-h">{{ gameInfo.curissuestatus==='2'||gameInfo.timeH<0?'--':gameInfo.timeH<10?'0'+gameInfo.timeH: gameInfo.timeH }}</div>：
            <div class="time-h">{{ gameInfo.curissuestatus==='2'||gameInfo.timeM<0?'--':gameInfo.timeM<10?'0'+gameInfo.timeM: gameInfo.timeM }}</div>：
            <div class="time-h">{{ gameInfo.curissuestatus==='2'||gameInfo.timeS<0?'--':gameInfo.timeS<10?'0'+gameInfo.timeS: gameInfo.timeS }}</div>
          </div>
        </div>
      </div>
    </div>
    <div class="tab-content">
      <div v-for="(item, index) in tabList" :key="index" class="tab-item" :class="{active: currentTab === item.value}" @click="tabChange(item.value)">{{ item.label }}</div>
    </div>
    <div v-if="currentTab === 0" class="betting-area">
      <div class="buy-area">
        <div class="left-menu">
          <div v-for="(item, index) in leftMenuList" :key="index" class="menu-item" :class="{active: currentGame === index}" @click="gameChange(index)">{{ item.playname1 }}</div>
        </div>
        <div v-if="currentGame===1||currentGame===3" class="right-content">
          <div v-for="(obj, i) in leftMenuList[currentGame].list" :key="i" class="game-group">
            <div class="group-title">{{ obj.playname2 }}</div>
            <div class="buy-list">
              <div v-for="(ele, j) in obj.list" :key="j" :class=" ele.active?ele.styleName+' active'+ele.color:ele.styleName" @click="ele.active =!ele.active">
                <div class="game-name">{{ ele.optionname }}</div>
                <div class="game-rate">{{ ele.odds }}</div>
              </div>
            </div>
          </div>
        </div>
        <div v-else-if="currentGame===2" class="right-content">
          <div v-for="(obj, i) in leftMenuList[currentGame].list" :key="i" class="game-group">
            <div class="group-title">{{ obj.playname2 }}</div>
            <div class="buy-list" v-for="(ele, j) in obj.list" :key="j" @click="ele.active =!ele.active">
              <div  :class=" ele.active?ele.styleName+' active':ele.styleName">
                <div class="game-name">{{ ele.optionname }}</div>
                <div class="game-rate">{{ ele.odds }}</div>
              </div>
              <template v-if="ele.remark.split(',').length>9">
                <div :class="ele.active?ele.remark.split(',')[1]+' circle-snake':'circle-snake'" >{{ ele.remark.split(',')[0] }}</div>
                <div :class="ele.active?ele.remark.split(',')[3]+' circle-snake':'circle-snake'" >{{ ele.remark.split(',')[2] }}</div>
                <div :class="ele.active?ele.remark.split(',')[5]+' circle-snake':'circle-snake'" >{{ ele.remark.split(',')[4] }}</div>
                <div :class="ele.active?ele.remark.split(',')[7]+' circle-snake':'circle-snake'" >{{ ele.remark.split(',')[6] }}</div>
                <div :class="ele.active?ele.remark.split(',')[9]+' circle-snake':'circle-snake'" >{{ ele.remark.split(',')[8] }}</div>
              </template>
              <template v-else>
                <div :class="ele.active?ele.remark.split(',')[1]+' circle':'circle'" >{{ ele.remark.split(',')[0] }}</div>
                <div :class="ele.active?ele.remark.split(',')[3]+' circle':'circle'" >{{ ele.remark.split(',')[2] }}</div>
                <div :class="ele.active?ele.remark.split(',')[5]+' circle':'circle'" >{{ ele.remark.split(',')[4] }}</div>
                <div :class="ele.active?ele.remark.split(',')[7]+' circle':'circle'" >{{ ele.remark.split(',')[6] }}</div>
              </template>
            </div>
          </div>
        </div>
        <div v-else class="right-content1">
          <div v-if="leftMenuList[currentGame].list" class="typeList">
            <div v-for="(obj, i) in leftMenuList[currentGame].list" :key="i" :class="obj.active?'type-item active':'type-item'" @click="typeChange(i)">{{ obj.playname2 }}</div>
          </div>
          <div class="game-group" v-if="leftMenuList[currentGame].list.filter(item => item.active).length>0">
            <!-- <div class="group-title">{{ obj.playname2 }}</div> -->
            <div v-if="leftMenuList[currentGame].list.find(item => item.active).playname2.includes('肖')">
              <div class="buy-list" v-for="(ele, j) in leftMenuList[currentGame].list.find(item => item.active).list" :key="j" @click="ele.active =!ele.active">
                <div  :class=" ele.active?ele.styleName+' active':ele.styleName">
                  <div class="game-name">{{ ele.optionname }}</div>
                  <div class="game-rate">{{ ele.odds }}</div>
                </div>
                <template v-if="ele.remark.split(',').length>9">
                  <div :class="ele.active?ele.remark.split(',')[1]+' circle-snake':'circle-snake'" >{{ ele.remark.split(',')[0] }}</div>
                  <div :class="ele.active?ele.remark.split(',')[3]+' circle-snake':'circle-snake'" >{{ ele.remark.split(',')[2] }}</div>
                  <div :class="ele.active?ele.remark.split(',')[5]+' circle-snake':'circle-snake'" >{{ ele.remark.split(',')[4] }}</div>
                  <div :class="ele.active?ele.remark.split(',')[7]+' circle-snake':'circle-snake'" >{{ ele.remark.split(',')[6] }}</div>
                  <div :class="ele.active?ele.remark.split(',')[9]+' circle-snake':'circle-snake'" >{{ ele.remark.split(',')[8] }}</div>
                </template>
                <template v-else>
                  <div :class="ele.active?ele.remark.split(',')[1]+' circle':'circle'" >{{ ele.remark.split(',')[0] }}</div>
                  <div :class="ele.active?ele.remark.split(',')[3]+' circle':'circle'" >{{ ele.remark.split(',')[2] }}</div>
                  <div :class="ele.active?ele.remark.split(',')[5]+' circle':'circle'" >{{ ele.remark.split(',')[4] }}</div>
                  <div :class="ele.active?ele.remark.split(',')[7]+' circle':'circle'" >{{ ele.remark.split(',')[6] }}</div>
                </template>
                <!-- <div :class="ele.active?ele.remark.split(',')[1]+' circle':'circle'" >{{ ele.remark.split(',')[0] }}</div>
                <div :class="ele.active?ele.remark.split(',')[3]+' circle':'circle'" >{{ ele.remark.split(',')[2] }}</div>
                <div :class="ele.active?ele.remark.split(',')[5]+' circle':'circle'" >{{ ele.remark.split(',')[4] }}</div>
                <div :class="ele.active?ele.remark.split(',')[7]+' circle':'circle'" >{{ ele.remark.split(',')[6] }}</div>
                <div v-if="ele.optionname==='蛇'" :class="ele.active?ele.remark.split(',')[9]+' circle':'circle'" >{{ ele.remark.split(',')[8] }}</div> -->
              </div>
            </div>
            <div v-else class="buy-list" >
              <div v-for="(ele, j) in leftMenuList[currentGame].list.find(item => item.active).list" :key="j" :class=" ele.active?ele.styleName+' active'+ele.color:ele.styleName" @click="ele.active =!ele.active">
                <div class="game-name">{{ ele.optionname }}</div>
                <div class="game-rate">{{ ele.odds }}</div>
              </div>
            </div>
          </div>
        </div>
      </div>
      <!-- <div class="split-line"></div> -->
      <div class="submit-area">
        <div class="bet-title">
          <div class="bet-label">每注押注</div>
          <div v-if="minBetMoney && maxBetMoney">限红：<span class="bet-tip">{{ minBetMoney }}~{{ maxBetMoney }}元</span></div>
        </div>
        <div class="bet-area">
          <div v-for="(item,index) in betMonsList" :key="index" :class="betMoney===item.value?'betSpan onSelectSpan':'betSpan'" @click="selectBetMons(item,index)">{{ item.label }}</div>
          <input v-model="betMoney" class="bet-input" step="1" type="number" placeholder="请输入投注金额" @input="inputChange">
        </div>
        <div class="button-line">
          <div class="clear-btn" @click="clearData()">
            <div class="btn-icon" />
            <span>清空</span>
          </div>
          <div v-if="gameInfo.curissuestatus==='0'" class="submit-btn" @click="submitBet">
            <span class="btn-text">立即下注</span>
            <span class="btn-tip">已选{{ betNum }}注，共计{{ betMoney*betNum }}元</span>
          </div>
          <div v-else class="opening">{{ gameInfo.curissuestatus==='1'?'已封单':gameInfo.curissuestatus==='2'?'开奖中':'' }}</div>
        </div>
      </div>
    </div>
    <div v-if="currentTab === 1" class="route-map">
      <route-map />
    </div>
    <buy-list v-if="currentTab === 2" />
    <div v-if="currentTab === 3" class="rule-content">
      <img :src="remarkpic" style="width:100%;" alt="">
    </div>
    <open-list v-if="showOpenList" />
  </div>
</template>

<script>
import TitleLineNum from './modules/canada/TitleLineNumCanada.vue'
import RouteMap from './modules/HKlhc/RouteMap.vue'
import OpenList from './modules/HKlhc/OpenList.vue'
import BuyList from './modules/HKlhc/BuyList.vue'
import { getOpeninfo, getGameinfo, save, getremarkpic } from '@/api/hklhc'
export default {
  name: 'GameHKlhc',
  components: {
    TitleLineNum,
    RouteMap,
    OpenList,
    BuyList
  },
  data() {
    return {
      gametype: '',
      showOpenList: false,
      title: this.$route.query.title||'香港六合彩', // 标题
      gameInfo: {
        // openissue: '001', // 期号
        // curissue: '002', // 开奖日期
        // open1:'3',
        // open2:'4',
        // open3:'5',
        // opensum:'6',
        // timeH:'00',
        // timeM:1,
        // timeS:5,
        // curissuestatus:'2',//'0' 可购买，'1' 已封单，'2' 开奖中
        // curissuecountdown: "134",
      },
      betMonsList:[{label: '5',value: '5',onSelect: false},{label: '50',value: '50',onSelect: false},{label: '100',value: '100',onSelect: false},{label: '1k',value: '1000',onSelect: false}],
      currentTab: 0,
      currentGame: 0,
      tabList: [{ label: '投注区', value: 0 }, { label: '路单图', value: 1 }, { label: '游戏记录', value: 2 }, { label: '游戏规则', value: 3 }],
      leftMenuList: [
        {
          label: 'playname1', value: 'tmzh', list: [{
            label: 'playname2',
            list: [{
              optionname: '大', value: 1, odds: 1.996, active: false }, {
              optionname: '小', value: 2, odds: 1.996, active: false }, {
              optionname: '单', value: 3, odds: 1.996, active: false }, {
              optionname: '双', value: 4, odds: 1.996, active: false
            }]
          }, {
            label: '组合',
            list: [{
              optionname: '大单', value: 1, odds: 1.996 }, {
              optionname: '大双', value: 2, odds: 1.996 }, {
              optionname: '小单', value: 3, odds: 1.996 }, {
              optionname: '小双', value: 4, odds: 1.996
            }]
          }, {
            label: '极大小',
            list: [{
              optionname: '极大', value: 1, odds: 1.996 }, {
              optionname: '极小', value: 2, odds: 1.996
            }]
          }]
        }, {
          label: '双面定位', value: 'smdw', list: [{
            label: '百位',
            list: [{
              optionname: '大', value: 0, odds: 1.996 }, {
              optionname: '小', value: 1, odds: 1.996 }, {
              optionname: '单', value: 2, odds: 1.996 }, {
              optionname: '双', value: 3, odds: 1.996 }, {
              optionname: '0', value: 0, odds: 1.996 }, {
              optionname: '1', value: 1, odds: 1.996 }, {
              optionname: '2', value: 2, odds: 1.996 }, {
              optionname: '3', value: 3, odds: 1.996 }, {
              optionname: '4', value: 3, odds: 1.996
            }]
          }]
        }
      ],
      betMoney: '',
      maxBetMoney: null,
      minBetMoney: null,
      // betNum:0,
      remarkpic: '',
      interval: null
    }
  },
  computed: {
    betNum() {
      let num = 0
      this.maxBetMoney = null
      this.minBetMoney = null
      for (let i = 0; i < this.leftMenuList[this.currentGame].list.length; i++) {
        for (let j = 0; j < this.leftMenuList[this.currentGame].list[i].list.length; j++) {
          if (this.leftMenuList[this.currentGame].list[i].list[j].active) {
            num++
            if (this.maxBetMoney && Number(this.maxBetMoney) < Number(this.leftMenuList[this.currentGame].list[i].list[j].limitmax)) {
              // this.maxBetMoney=this.leftMenuList[this.currentGame].list[i].list[j].limitmax
              // this.minBetMoney=this.leftMenuList[this.currentGame].list[i].list[j].limitmin
            } else {
              this.maxBetMoney = this.leftMenuList[this.currentGame].list[i].list[j].limitmax
            }
            if (this.minBetMoney && Number(this.minBetMoney) > Number(this.leftMenuList[this.currentGame].list[i].list[j].limitmin)) {
              // this.maxBetMoney=this.leftMenuList[this.currentGame].list[i].list[j].limitmax
              // this.minBetMoney=this.leftMenuList[this.currentGame].list[i].list[j].limitmin
            } else {
              this.minBetMoney = this.leftMenuList[this.currentGame].list[i].list[j].limitmin
            }
          }
        }
      }
      if(this.leftMenuList[this.currentGame].playname1==='自选不中'||this.leftMenuList[this.currentGame].playname1==='连码'||this.leftMenuList[this.currentGame].playname1==='连肖连尾'){
        const item=this.leftMenuList[this.currentGame].list.find(item=>item.active)
        num = this.generateCombinations(num,item.limitSelect)
      }
      return num
    },
  },
  created() {
    this.$socket.open()
    this.sockets.subscribe('getJndHkLhcOpenIfo', (res) => {

      console.log(res)
      const data = JSON.parse(res)
      if(this.gameInfo.curissue!==data.curissue){
        this.$store.dispatch('user/getInfo') // 更新余额
      }
      data.timeS = Number(data.curissuecountdown % 60)
      data.timeM = Math.floor((data.curissuecountdown % 3600) / 60);
      data.timeH = Math.floor(data.curissuecountdown / 3600)
      this.gameInfo = data
      if (!this.interval) {
        this.interval = setInterval(() => {
          // if (this.gameInfo.timeS === 0) {
          //   if (this.gameInfo.timeM === 0) {
          //     this.gameInfo.timeH = 0
          //     this.gameInfo.timeM = 0
          //     this.gameInfo.timeS = 0
          //     clearInterval(this.interval)
          //     this.interval = null
          //   } else {
          //     this.gameInfo.timeM--
          //     this.gameInfo.timeS = 59
          //   }
          // } else {
          //   this.gameInfo.timeS--
          // }
          this.gameInfo.curissuecountdown--
          this.gameInfo.timeS = Number(this.gameInfo.curissuecountdown % 60)
          this.gameInfo.timeM = Math.floor((this.gameInfo.curissuecountdown % 3600) / 60);
          this.gameInfo.timeH = Math.floor(this.gameInfo.curissuecountdown / 3600)
        }, 1000)
      }
    })
    this.gametype = this.$route.query.id.substring(4, 9)
    getOpeninfo({ gametype: this.gametype }).then(res => {
      // res.curissuestatus='0'
      res.timeS = Number(res.curissuecountdown % 60)
      res.timeM = Math.floor((res.curissuecountdown % 3600) / 60);
      res.timeH = Math.floor(res.curissuecountdown / 3600)
      // res.timeH=Math.floor(res.timeM/60)
      this.gameInfo = res
      // this.gameInfo.curissuestatus='0'
    }).catch(err=>{
      console.log(err);
    })
    getGameinfo({ gametype: this.gametype }).then(res => {
      this.leftMenuList = res.gamelist
    }).catch(err=>{
      console.log(err);
    });
  },
  mounted() {
    this.interval = setInterval(() => {
      // if (this.gameInfo.timeS === 0) {
      //   if (this.gameInfo.timeM === 0) {
      //     this.gameInfo.timeH = 0
      //     this.gameInfo.timeM = 0
      //     this.gameInfo.timeS = 0
      //     clearInterval(this.interval)
      //     this.interval = null
      //   } else {
      //     this.gameInfo.timeM--
      //     this.gameInfo.timeS = 59
      //   }
      // } else {
      //   this.gameInfo.timeS--
      // }
      this.gameInfo.curissuecountdown--
      this.gameInfo.timeS = Number(this.gameInfo.curissuecountdown % 60)
      this.gameInfo.timeM = Math.floor((this.gameInfo.curissuecountdown % 3600) / 60);
      this.gameInfo.timeH = Math.floor(this.gameInfo.curissuecountdown / 3600)
    }, 1000)
    setTimeout(() => {
      window.scrollTo(0, 50)
    })
  },
  beforeDestroy() {
    if (this.interval) {
      clearInterval(this.interval)
      this.interval = null
    }
    // const gametype = this.$route.query.id.substring(4, 9)
    this.sockets.unsubscribe('getJndHkLhcOpenIfo')
    this.$socket.close()
  },
  methods: {
    generateCombinations(arrLength, k) {
      arrLength = Number(arrLength);
      k = Number(k);
      if (k > arrLength) return 0;
      let result = 1;
      let cresult = 1;
      for (let i = 1; i <= k; i++) {
        result = result * (arrLength - i + 1);
      }
      for (let c=1;c<=k;c++){
        cresult = cresult * c
      }
      result = result / cresult;
      return result;
    },
    typeChange(i){
      this.leftMenuList[this.currentGame].list.forEach(item => {
        if(item.active){
          item.active = false
        }
        item.list.forEach(ele => {
          ele.active = false
        })
      })
      this.leftMenuList[this.currentGame].list[i].active=true
    },
    selectBetMons(item,index){
      if(item.onSelect){
        this.betMoney = ''
      }else {
        this.betMoney = item.value
        this.betMonsList.forEach(item => {
          item.onSelect=false
        })
      }
      item.onSelect = !item.onSelect
      
      
    },
    // 限制输入框只能输入数字，不允许输入小数点
    inputChange(e) {
      console.log(e.target.value)
      e.target.value = e.target.value.replace(/[^\d]/g, '')
      if (this.betMoney.includes('.')) {
        this.$toast('投注金额不能包含小数点')
        this.betMoney = this.betMoney.replace('.', '')
      }
    },
    tabChange(val) {
      this.currentTab = val
      if (val === 3) {
        getremarkpic({ gametype: this.gametype }).then(res => {
          this.remarkpic = res.remarkpic
        })
      }
    },
    gameChange(val) {
      this.currentGame = val
      for (let index = 0; index < this.leftMenuList.length; index++) {
        for (let index2 = 0; index2 < this.leftMenuList[index].list.length; index2++) {
          for (let index3 = 0; index3 < this.leftMenuList[index].list[index2].list.length; index3++) {
            this.leftMenuList[index].list[index2].list[index3].active = false
          }
        }
      }
    },
    submitBet() {
      const betList = []
      for (let i = 0; i < this.leftMenuList[this.currentGame].list.length; i++) {
        for (let j = 0; j < this.leftMenuList[this.currentGame].list[i].list.length; j++) {
          if (this.leftMenuList[this.currentGame].list[i].list[j].active) {
            betList.push(this.leftMenuList[this.currentGame].list[i].list[j].optioncode1 + ',' + this.leftMenuList[this.currentGame].list[i].list[j].optioncode2 + ',' + this.betMoney)
          }
        }
      }
      const limitSelect = this.leftMenuList[this.currentGame].list.find(item => item.active).limitSelect
      const limitSelectMax = this.leftMenuList[this.currentGame].list.find(item => item.active).limitSelectMax
      if(limitSelect&&betList.length<limitSelect){
        this.$toast('请至少选择'+limitSelect+'个投注项目')
      }else if(limitSelectMax&&betList.length>limitSelectMax){
        this.$toast('最多只能选择'+limitSelectMax+'个投注项目')
      }else if (betList.length === 0) {
        this.$toast('请选择投注项目')
      } else if (!this.betMoney || this.betMoney === 0) {
        this.$toast('请输入投注金额')
      } else if (Number(this.betMoney) < Number(this.minBetMoney)) {
        this.$toast('投注金额不能低于' + this.minBetMoney)
      } else if (Number(this.betMoney) > Number(this.maxBetMoney)) {
        this.$toast('投注金额不能高于' + this.maxBetMoney)
      } else if (this.betMoney.includes('.')) {
        this.$toast('投注金额不能包含小数点')
        // this.betMoney = this.betMoney.replace('.', '')
        this.betMoney = null
      } else {
        if (this.betMoney > 0) {
          save({
            gametype: this.gametype,
            buyissue: this.gameInfo.curissue,
            buytype: betList.join(';')
          }).then(res => {
            this.clearData()
            this.$store.dispatch('user/getInfo') // 更新余额
            this.$toast.success('下注成功')
          })
        }
      }
    },
    clearData() {
      this.betMoney = null
      this.leftMenuList[this.currentGame].list.forEach(item => {
        item.list.forEach(ele => {
          ele.active = false
        })
      })
      this.betMonsList.forEach(item => {
          item.onSelect=false
      })
    }
  },
  sockets: {
    // 链接成功
    connect(data) {
      console.log(data)
    },
    // 发送消息
    toServer(data) {
      this.$socket.emit('toServer', data)
    },
    // 接收消息
    toClient(data) {
      this.msgList.push(data)
    },
    // 断开链接回调
    disconnect() {
