<template>
  <div class="buy-list">
    <div class="detailListLhc">
      <van-pull-refresh v-model="refreshing" :loading-text="$t('tzjl.tzjl50')" :pulling-text="$t('tzjl.tzjl51')" :loosing-text="$t('tzjl.tzjl52')" :finished-text="$t('tzjl.tzjl53')" @refresh="onRefresh">
        <van-list
          v-model="loading"
          :finished="finished"
          :loading-text="$t('tzjl.tzjl50')"
          finished-text=""
          @load="onLoad"
        >
          <is-empty v-if="recordList.length===0" />
          <div v-for="(item,index) in recordList" :key="index" class="list-box">
            <div v-for="(ele,j) in item" :key="j" class="detail">
              <span>{{ ele.label }}</span>
              <div v-if="ele.label==='开奖号码'" class="openNum">
                <!-- <div v-for="(obj,k) in ele.value.split('') " :key="k" :class="'dice'+obj" /> -->
                <div v-if="ele.value.split(';')[0]" class="open-info">
                  <div class="open-item" v-for="i in 7" :key="i">
                    <div :class="'open '+ele.value.split(';')[i-1].split(',')[2]+'_bg'" >{{ ele.value.split(';')[i-1].split(',')[0] }}</div>
                    <div class="text-line">{{ ele.value.split(';')[i-1].split(',')[1]+'/'+ele.value.split(';')[i-1].split(',')[3] }}</div>
                  </div>
                </div>
              </div>
              <span v-else-if="ele.label===$t('tzjl.tzjl18')||ele.label===$t('tzjl.tzjl40')||ele.label===$t('tzjl.tzjl35')||ele.label===$t('tzjl.tzjl22')||ele.label===$t('tzjl.tzjl25')||ele.label===$t('tzjl.tzjl29')||ele.label===$t('tzjl.tzjl36')">{{ ele.value }}</span>
              <span v-else-if="ele.label===$t('tzjl.tzjl39')" :class="ele.value.includes('-')?'red': 'green'">{{ ele.value }}</span>
              <span v-else-if="ele.label===$t('tzjl.tzjl23')&&(ele.value==='中奖'||ele.value==='待开奖')" class="green">{{ ele.value }}</span>
              <span v-else-if="ele.label===$t('tzjl.tzjl23')&&ele.value==='未中奖'" class="red">{{ ele.value }}</span>
              <span v-else-if="ele.label===$t('tzjl.tzjl23')&&ele.value==='和局'" class="yellow">{{ ele.value }}</span>
              <span v-else-if="ele.label===$t('tzjl.tzjl24')||ele.label===$t('tzjl.tzjl37')" class="yellow">{{ ele.value }}</span>
              <!-- <span v-else-if="ele.label==='钱包地址'" class="">{{ ele.showValue }}</span> -->
              <div v-else class="Period">
                <span v-if="ele.label===$t('tzjl.tzjl28')||ele.label===$t('tzjl.tzjl27')">{{ ele.showValue }}</span>
                <span v-else>{{ ele.value }}</span>
                <div class="copy-icon" @click="doCopy(ele.value)" />
                <span v-if="ele.label===$t('tzjl.tzjl28')" class="verify" @click="goVerify(item.find(obj=>obj.label===$t('tzjl.tzjl26')).value)">{{ $t('tzjl.tzjl30') }}</span>
              </div>
            </div>
          </div>
        </van-list>
      </van-pull-refresh>
    </div>
  </div>
</template>
<script>
import { getBuyList } from '@/api/hklhc'
export default {
  name: 'BuyList',
  data() {
    return {
      recordList: [],
      loading: false,
      finished: false,
      refreshing: false,
      pageNum: 1,
      pageSize: 10
    }
  },
  created() {
  },
  methods: {
    onLoad() {
      getBuyList({ gametype: this.$route.query.id.substring(4, 9), pages: this.pageNum }).then(res => {
        if (this.refreshing) {
          this.recordList = []
          this.refreshing = false
        }
        this.recordList = this.recordList.concat(res.recordList)
        this.loading = false
        this.pageNum++
        if (this.recordList.length >= Number(res.totalrow)) {
          this.finished = true
        }
      })
    },
    onRefresh() {
      // 清空列表数据
      this.finished = false
      this.pageNum = 1
      this.refreshing = true
      // 重新加载数据
      // 将 loading 设置为 true，表示处于加载状态
      this.loading = true
      this.onLoad()
    },
    goVerify(val) {
      // window.open('https://tronscan.org/#/block/' + val)
      this.$router.push({
        path: '/verifyIndex',
        query: {
          block: val,
          blockurl: ''
        }
      })
    },
    doCopy(val) {
      this.$copyText(val).then(
        (e) => {
          // success
          this.$toast.success(this.$t('yqhy.yqhy10'))
        },
        (e) => {
          // fail
          console.log(e)
        }
      )
    }
  }
}
</script>
